#!/usr/bin/env bash
# Build the Zenodo data archive from a completed `make all`. Code is not included: it is released
# separately (see CODE_URL in epngcat/s13_final_catalog.py).
# Usage: tools/make_release.sh [name]   (default name: ePNGCAT; writes <name>.tar.gz in the repo root)
# Contents are listed in the "Released files" section of CATALOG_README.md (generated by step 13).
set -euo pipefail

cd "$(dirname "$0")/.."
name="${1:-ePNGCAT}"

files=(
    erass1_allsky.png
    out/13_final/erass1_image_catalog.fits
    out/13_final/erass1_image_catalog.csv
    out/13_final/uncertainty_calibration.json
    out/17_orphans/ru_candidates.csv
    out/17_orphans/ru_candidates.parquet
    out/16_healpix/healpix_data_nside1024.fits
    out/16_healpix/healpix_clean_nside1024.fits
    out/16_healpix/healpix_clean_filled_nside1024.fits
    out/run_manifest.json
)

for f in CATALOG_README.md "${files[@]}"; do
    [[ -e "$f" ]] || { echo "missing: $f" >&2; exit 1; }
done
# The run record is written last; anything newer than it was changed after the release run.
[[ out/.stamps/provenance -nt out/13_final/erass1_image_catalog.fits ]] \
    || { echo "out/.stamps/provenance is older than the catalogue: run 'make all' first" >&2; exit 1; }

stage="$(mktemp -d)"
trap 'rm -rf "$stage"' EXIT
mkdir "$stage/$name"
cp CATALOG_README.md "$stage/$name/README.md"
# rsync -R keeps the repository-relative paths the README refers to.
rsync -aR --exclude '__pycache__' --exclude '.DS_Store' "${files[@]}" "$stage/$name/"

COPYFILE_DISABLE=1 tar -C "$stage" -czf "$name.tar.gz" "$name"
echo "wrote $name.tar.gz ($(du -h "$name.tar.gz" | cut -f1))"
echo "files: $(tar -tzf "$name.tar.gz" | grep -vc '/$')"
